// ========================================================
// 📐 数据规范化引擎 (Canonical Data Model)
// 将所有不同格式的输入统一为单一数据结构
// ========================================================

const items = $input.all();
const canonical_items = [];

function sanitize(s) {
  if (s == null) return '';
  s = String(s);
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ');
  s = s.replace(/\r\n?/g, '\n');
  return s.trim();
}

for (const item of items) {
  const json = item.json || {};
  let canonical = {};

  // 🔹 识别数据源并映射字段
  if (json.items && Array.isArray(json.items)) {
    // FreshRSS格式
    for (const rssItem of json.items) {
      canonical = {
        title: sanitize(rssItem.title),
        url: sanitize(rssItem.canonical?.[0]?.href || rssItem.alternate?.[0]?.href),
        content: sanitize(rssItem.summary?.content || rssItem.content?.content),
        source_platform: sanitize(rssItem.origin?.title || 'FreshRSS'),
        source_type: 'rss_feed',
        pub_date: rssItem.published ? new Date(rssItem.published * 1000).toISOString() : new Date().toISOString(),
        raw_data: JSON.stringify(rssItem)
      };

      if (canonical.url && canonical.title) {
        canonical_items.push({ json: canonical });
      }
    }
  } else if (json.result?.extracted_data) {
    // Scrapfly格式
    const extracted = json.result.extracted_data;
    const dataArray = Array.isArray(extracted) ? extracted : [extracted];

    for (const scrapeItem of dataArray) {
      canonical = {
        title: sanitize(scrapeItem.title || scrapeItem.headline),
        url: sanitize(json.result.url || scrapeItem.link),
        content: sanitize(scrapeItem.summary || scrapeItem.content || scrapeItem.description),
        source_platform: sanitize(scrapeItem.source || new URL(json.result.url).hostname),
        source_type: 'web_scrape',
        pub_date: scrapeItem.date || scrapeItem.published_date || new Date().toISOString(),
        raw_data: JSON.stringify(scrapeItem)
      };

      if (canonical.url && canonical.title) {
        canonical_items.push({ json: canonical });
      }
    }
  }
}

console.log(`✅ 规范化完成: ${canonical_items.length} 条记录`);

return canonical_items.length > 0 ? canonical_items : [{ json: { _skip: true } }];

// ========================================================
// 🧹 去重过滤器
// ========================================================

const newItems = $input.first().json;
const existingData = $input.last().json;

const existingUrls = new Set();

if (existingData?.data?.items) {
  for (const record of existingData.data.items) {
    const url = record.fields?.URL;
    if (url) {
      // 处理飞书URL字段（可能是数组格式）
      const urlText = Array.isArray(url) ? url[0]?.text : url;
      if (urlText) existingUrls.add(urlText);
    }
  }
}

console.log(`📊 数据库中已有 ${existingUrls.size} 条URL记录`);

const filtered = [];
for (const item of newItems) {
  if (item._skip) continue;
  if (!existingUrls.has(item.url)) {
    filtered.push({ json: item });
  }
}

console.log(`✅ 过滤后剩余 ${filtered.length} 条新记录`);

return filtered.length > 0 ? filtered : [{ json: { _no_new_items: true } }];

// ========================================================
// 🔍 程序化分诊评分 (Triage Scoring)
// 目的：快速、免费地过滤掉90%的噪音
// ========================================================

const item = $json;
if (item._no_new_items || item._skip) {
  return { json: item };
}

let triage_score = 0;

// 🔹 1. 高价值关键词 (50分)
const high_value_keywords = [
  'STRIKE', '罢工',
  'PORT CLOSURE', '港口关闭',
  'SUSPENSION', '暂停',
  'RATE INCREASE', '运费上涨',
  'DELAY', '延误',
  'DISRUPTION', '中断',
  'EMERGENCY', '紧急',
  'ALERT', '警报',
  'FEE CHANGE', '费用变更',
  'SERVICE UPDATE', '服务更新',
  'TARIFF', '关税',
  'CUSTOMS', '海关'
];

const titleUpper = (item.title || '').toUpperCase();
const contentUpper = (item.content || '').toUpperCase();
const fullText = titleUpper + ' ' + contentUpper;

const matchedKeywords = high_value_keywords.filter(k => fullText.includes(k));
if (matchedKeywords.length > 0) {
  triage_score += Math.min(matchedKeywords.length * 15, 50);
}

// 🔹 2. 高价值来源 (40分)
const high_value_sources = [
  'maersk.com',
  'msc.com',
  'cma-cgm.com',
  'ups.com',
  'fedex.com',
  'dhl.com',
  'amazon.com/seller',
  'shopify.com/changelog'
];

const source = (item.source_platform || '').toLowerCase();
if (high_value_sources.some(s => source.includes(s))) {
  triage_score += 40;
}

// 🔹 3. Web Scrape优先（专有数据）(30分)
if (item.source_type === 'web_scrape') {
  triage_score += 30;
}

// 🔹 4. 内容丰富度 (10分)
if (item.content && item.content.length > 500) {
  triage_score += 10;
}

// 🔹 5. 时效性（新鲜度）
const pubDate = new Date(item.pub_date);
const hoursAgo = (Date.now() - pubDate.getTime()) / (1000 * 60 * 60);
if (hoursAgo < 24) {
  triage_score += 10;
} else if (hoursAgo < 72) {
  triage_score += 5;
}

return {
  json: {
    ...item,
    triage_score: Math.min(triage_score, 100),
    matched_keywords: matchedKeywords.join(', ')
  }
};

// ========================================================
// 📝 生成AI摘要提示词
// ========================================================

const item = $json;

const prompt = `你是一名专业的物流行业分析师。请将以下新闻总结为100字以内的事实性、中立性摘要。

标题：${item.title}
来源：${item.source_platform}
内容：${item.content.substring(0, 2000)}

要求：
1. 只陈述事实，不要加入评论
2. 突出关键数字、地点、公司名称
3. 100字以内
4. 用中文输出`;

return {
  json: {
    ...item,
    ai_summary_prompt: prompt
  }
};

// ========================================================
// 🤖 AI深度评分提示词生成器（JSON Schema约束）
// ========================================================

const item = $json;

const scoringPrompt = `PERSONA:
你是一名专业的 B2B 物流分析师，同时也是一名病毒式社交媒体新闻制作人。你的受众是航运、货运和电子商务领域忙碌的专业人士。

TASK:
分析以下新闻摘要。根据你的专业知识，评估其制作成 60 秒

因子)。
4. **Relatability (相关性) (1-5):** 这与普通的货运代理、仓库经理或亚马逊卖家的相关性如何？ (1 = 纯学术, 5 = 直接影响他们的日常工作)。

OUTPUT INSTRUCTIONS:
仅返回一个有效的 JSON 对象，严格遵循以下格式：
{
  "impact_score": <number 1-10>,
  "urgency_score": <number 1-5>,
  "virality_score": <number 1-5>,
  "relatability_score": <number 1-5>,
  "final_score": <number, 计算公式: (Impact*0.4) + (Urgency*0.3) + (Virality*0.2) + (Relatability*0.1)>,
  "justification": "<对最终分数的简短理由陈述，50字以内>",
  "suggested_hook": "<从新闻中提取的最强'钩子'，10个词以内>"
}`;

return {
  json: {
    ...item,
    ai_scoring_prompt: scoringPrompt
  }
};

// ========================================================
// 📦 构建飞书写入Body（批量）
// ========================================================

const items = $input.all();

function sanitize(s) {
  if (s == null) return '';
  s = String(s);
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ');
  s = s.replace(/\r\n?/g, '\n');
  return s.trim();
}

const records = items.map(it => {
  const j = it.json || {};
  return {
    fields: {
      "News_Title": sanitize(j.title),
      "Source": sanitize(j.source_platform),
      "URL": sanitize(j.url),
      "Received_At": new Date().toISOString(),
      "Status": "Pending",
      "AI_Triage_Score": Number(j.triage_score) || 0,
      "AI_Final_Score": Number(j.ai_final_score) || 0,
      "AI_Justification": sanitize(j.ai_justification),
      "AI_Suggested_Hook": sanitize(j.ai_suggested_hook),
      "Keywords": sanitize(j.matched_keywords)
    }
  };
});

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) {
    out.push(arr.slice(i, i + size));
  }
  return out;
}

const chunks = chunk(records, 100);

console.log(`📦 准备写入 ${chunks.length} 个批次，共 ${records.length} 条`);

return chunks.map(part => ({
  json: {
    body: JSON.stringify({ records: part })
  }
}));
